    96	async function sendWithRetry<T>(
    97	  method: HttpMethod,
    98	  path: string,
    99	  body: string | undefined,
   100	  options: RequestOptions,
   101	): Promise<T> {
   102	  for (let attempt = 0; ; attempt++) {
   103	    try {
   104	      return await send<T>(method, path, body, options.signal);
   105	    } catch (e) {
   106	      const retryable =
   107	        options.idempotent === true &&
   108	        (e instanceof NetworkError || (e instanceof ApiError && e.status === 503));
   109	      if (!retryable || attempt >= RETRY_DELAYS_MS.length) throw e;
   110	      await sleep(RETRY_DELAYS_MS[attempt], options.signal);
   111	    }
