   115	async function send<T>(
   116	  method: HttpMethod,
   117	  path: string,
   118	  body: string | undefined,
   119	  signal: AbortSignal | undefined,
   120	): Promise<T> {
   121	  const headers: Record<string, string> = { Accept: 'application/json' };
   122	  if (body !== undefined) headers['Content-Type'] = 'application/json';
   123	  let res: Response;
   124	  let text: string;
   125	  try {
   126	    res = await fetch(path, { method, credentials: 'same-origin', headers, body, signal });
   127	    text = res.status === 204 ? '' : await res.text();
   128	  } catch (e) {
   129	    if (isAbort(e)) throw e;
   130	    throw new NetworkError(e);
   131	  }
   132	  if (res.ok) return (text === '' ? undefined : JSON.parse(text)) as T;
   133	  throw toApiError(res, text);
   134	}
