   136	function toApiError(res: Response, text: string): ApiError {
   137	  try {
   138	    const parsed: unknown = JSON.parse(text);
   139	    if (
   140	      parsed &&
   141	      typeof parsed === 'object' &&
   142	      typeof (parsed as { code?: unknown }).code === 'string'
