   161	      return;
   162	    }
   163	    const onAbort = () => {
   164	      clearTimeout(timer);
   165	      reject(signal?.reason);
   166	    };
   167	    const timer = setTimeout(() => {
   168	      signal?.removeEventListener('abort', onAbort);
   169	      resolve();
   170	    }, ms);
   171	    signal?.addEventListener('abort', onAbort, { once: true });
   172	  });
   173	}
